/* Finance screens extend the approved staff portal and use its account-scoped API. */
(() => {
'use strict';
const $=s=>document.querySelector(s),wf=()=>window.KsppsWorkflow;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'Rp'+Number(n||0).toLocaleString('id-ID');
const date=s=>s?new Date(s.length===10?s+'T12:00:00Z':s).toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Makassar'}):'—';
const today=()=>{const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Makassar',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}`};
const state={date:today(),followToday:true,items:[],payout:null,loaded:false,loading:false,error:'',query:'',filter:'',busy:false,sequence:0};
const announce=()=>window.dispatchEvent(new CustomEvent('kspps-finance-loaded'));
const role=()=>wf()?.getStaff()?.role||'admin';
const badge=r=>`<span class="badge ${r?.status==='approved'?'green':'amber'}">${esc(r?.label||'Menunggu Finance')}</span>`;
function heading(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtext">${description}</p></div>${action}</div>`}
const action=(a,label,attrs='')=>`<button type="button" class="btn secondary small-btn" data-finance-action="${a}" ${attrs}>${label}</button>`;
function table(headers,rows,empty){return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}"><div class="empty-state">${empty}</div></td></tr>`}</tbody></table></div>`}
function loading(){if(state.error)return `<div class="panel"><p class="form-error" role="alert">${esc(state.error)}</p>${action('refresh','Coba lagi')}</div>`;return '<div class="panel"><p class="muted" role="status">Memuat data Finance…</p></div>'}
function metrics(){const p=state.payout;return `<div class="stats finance-stats"><div class="stat"><div class="stat-top">Total bagi hasil</div><div class="stat-value finance-value">${money(p?.total)}</div><div class="stat-bottom">${date(state.date)} · 5% per akad</div></div><div class="stat"><div class="stat-top">Anggota penerima</div><div class="stat-value">${p?.memberCount||0}</div><div class="stat-bottom">${p?.transferCount||0} rekening tujuan</div></div><div class="stat"><div class="stat-top">Akad terjadwal</div><div class="stat-value">${p?.contractCount||0}</div><div class="stat-bottom">Pembayaran bulanan</div></div></div>`}
function queueTable(limit=0){const items=state.items.filter(x=>(!state.filter||x.reconciliation.status===state.filter)&&[x.memberName,x.memberId,x.label,x.proofName,x.projectCode].join(' ').toLowerCase().includes(state.query.toLowerCase()));return table(['ANGGOTA / SETORAN','NOMINAL','REKONSILIASI','TINDAKAN'],(limit?items.slice(0,limit):items).map(x=>`<tr><td><strong>${esc(x.memberName)}</strong><small>${esc(x.memberId||'—')} · ${esc(x.label)}</small>${x.projectCode?`<small class="offer-code">${esc(x.projectCode)}</small>`:''}</td><td class="money">${money(x.amount)}</td><td>${badge(x.reconciliation)}</td><td>${action('reconcile',x.reconciliation.status==='approved'?'Lihat':'Periksa',`data-id="${esc(x.id)}" data-kind="${x.kind}"`)}</td></tr>`).join(''),'Belum ada bukti transfer yang sesuai.');}
function dashboard(){const pending=state.items.filter(x=>x.reconciliation.status!=='approved').length;return heading('Ringkasan Finance','Rekonsiliasi setoran dan siapkan bagi hasil anggota.',`<span class="date-label">${date(state.date)}</span>`)+(!state.loaded||state.loading||state.error?loading():`${metrics()}<div class="finance-overview"><section class="panel"><div class="panel-head"><h2>Bukti transfer masuk</h2><span class="badge amber">${pending} perlu diperiksa</span></div>${queueTable(6)}<a class="link-button" href="#finance-rekonsiliasi">Lihat rekonsiliasi →</a></section><section class="panel"><div class="panel-head"><h2>Bagi hasil harian</h2></div><p class="subtext">Daftar transfer untuk ${date(state.date)} sudah dihitung dari akad yang dananya direkonsiliasi.</p><div class="wf-actions"><a class="btn" href="#finance-bagi-hasil">Buka daftar bagi hasil</a></div><p class="field-hint">Acuan: tanggal efektif nisbah. Pembayaran pertama satu bulan setelah tanggal efektif.</p></section></div>`)}
function queuePage(){return heading('Rekonsiliasi','Cocokkan bukti transfer anggota dengan mutasi rekening.',action('refresh','Perbarui'))+(!state.loaded||state.loading||state.error?loading():`<section class="panel"><div class="toolbar"><label class="search-wrap"><input class="search-input" id="finance-search" type="search" placeholder="Cari anggota atau jenis setoran…" aria-label="Cari setoran" value="${esc(state.query)}"></label><select class="filter-select" id="finance-filter" aria-label="Status rekonsiliasi"><option value="">Semua status</option>${[['pending','Menunggu Finance'],['correction','Perlu perbaikan'],['approved','Sudah direkonsiliasi']].map(([v,t])=>`<option value="${v}" ${state.filter===v?'selected':''}>${t}</option>`).join('')}</select></div><div id="finance-queue-table">${queueTable()}</div></section><p class="field-hint">Admin hanya dapat melanjutkan persetujuan atau pembuatan akad setelah Finance menyelesaikan rekonsiliasi.</p>`)}
function datePicker(){return `<div class="finance-date"><label for="finance-date">Tanggal pembayaran</label><input id="finance-date" type="date" min="1901-01-01" max="9998-12-31" value="${esc(state.date)}">${action('today','Hari ini')}</div>`}
function payoutPage(){const p=state.payout;return heading('Bagi Hasil Harian','Daftar nominal yang perlu ditransfer ke rekening anggota.',datePicker())+(!state.loaded||state.loading||state.error?loading():`${metrics()}${p?.task?(window.KsppsActivity?.panel(p.task.targetId,'payout')||''):''}${p?.task&&!p.task.completedAt?`<div class="wf-actions work-payout-action">${action('payout-complete','Selesaikan persiapan')}</div>`:''}<section class="panel"><div class="panel-head"><h2>Daftar transfer · ${date(state.date)}</h2>${action('csv','Unduh CSV',p?.members.length?'':'disabled')}</div>${p?.missingAccountCount?'<p class="form-error">Ada rekening yang belum lengkap. Periksa rincian anggota sebelum transfer.</p>':''}${table(['ANGGOTA','REKENING TUJUAN','AKAD','BAGI HASIL',''],(p?.members||[]).map((m,i)=>`<tr><td><strong>${esc(m.memberName)}</strong><small>${esc(m.memberId)}</small></td><td>${esc(m.bankName||'Bank belum tersedia')}<small class="finance-account">${esc(m.bankAccount||'Rekening belum tersedia')}</small><small>a.n. ${esc(m.accountName)}</small></td><td>${m.contractCount}</td><td class="money"><strong>${money(m.amount)}</strong></td><td>${action('detail','Rincian',`data-index="${i}"`)}</td></tr>`).join(''),'Tidak ada akad yang terjadwal pada tanggal ini.')}<div class="finance-total"><span>Total bagi hasil</span><strong>${money(p?.total)}</strong></div></section><details class="panel finance-method"><summary>Dasar perhitungan</summary><p>Bagi hasil per akad = nominal penyertaan modal × 5%. Sistem memilih tanggal efektif nisbah dari 12 bulan sebelumnya, dengan tanggal pembayaran bulanan yang jatuh hari ini. Nilai dibulatkan ke rupiah terdekat per akad, lalu dijumlahkan per anggota dan rekening.</p><div class="finance-dates">${(p?.referenceDates||[]).map(x=>`<span>${date(x)}</span>`).join('')}</div><p>Akad pada bulan berjalan belum masuk. Jadwal berhenti setelah tanggal selesai akad. Untuk tanggal 29 atau 30 yang tidak tersedia pada bulan pembayaran, jadwal jatuh pada hari terakhir bulan tersebut.</p></details><p class="field-hint">Daftar ini menyiapkan nominal transfer; tidak mengirim uang atau menandai transaksi bank sebagai berhasil.</p>`)}
function show(title,content){const modal=$('#portal-dialog');if(modal.open)modal.close();$('#dialog-content').innerHTML=`<div class="dialog-inner"><div class="dialog-head"><h2 id="dialog-title">${title}</h2>${action('close','Tutup')}</div>${content}</div>`;modal.showModal();window.KsppsActivity?.mount();}
function reconciliationDialog(id,kind){const x=state.items.find(i=>i.id===id&&i.kind===kind);if(!x)return;const r=x.reconciliation,done=['approved','correction'].includes(r.status)||x.sourceStatus==='correction';show('Rekonsiliasi '+x.label.toLowerCase(),`${window.KsppsActivity?.panel(x.id,'reconciliation')||''}<div class="status-head">${badge(r)}</div><dl class="review-list">${[...(x.projectCode?[['Kode project',x.projectCode],['Penawaran',x.offerTitle]]:[]),['Anggota',x.memberName],['Nomor anggota',x.memberId||'—'],['Nominal pengajuan',money(x.amount)],['Bukti transfer',x.proofName]].map(([a,b])=>`<div><dt>${a}</dt><dd>${esc(b)}</dd></div>`).join('')}</dl><div class="wf-actions"><a class="btn secondary" href="${esc(x.proofUrl)}" target="_blank" rel="noopener">Lihat bukti transfer</a></div>${done?`<dl class="review-list">${[['Dana diterima',money(r.receivedAmount)],['Tanggal dana masuk',date(r.transferDate)],['Referensi mutasi',r.reference],['Direkonsiliasi',date(r.checkedAt)],['Catatan',r.note||'—']].map(([a,b])=>`<div><dt>${a}</dt><dd>${esc(b)}</dd></div>`).join('')}</dl><p class="wf-note">${r.status==='approved'?(x.kind==='savings'?'Setoran simpanan wajib sudah masuk ke saldo anggota.':'Dana sudah direkonsiliasi oleh Finance. Admin dapat melanjutkan pemeriksaan.'):'Permintaan perbaikan sudah tampil di portal anggota. Bukti yang dikirim ulang akan masuk sebagai tugas baru.'}</p>`:`<form id="finance-reconcile-form" data-id="${esc(id)}" data-kind="${kind}" data-version="${r.version||0}" data-source-version="${x.sourceVersion}"><label class="form-field"><span>Nominal masuk di mutasi bank (Rp) *</span><input name="receivedAmount" type="number" min="0" max="10000000000000" step="1" inputmode="numeric" required placeholder="Isi sesuai mutasi bank"></label><label class="form-field"><span>Tanggal dana masuk *</span><input name="transferDate" type="date" min="1901-01-01" max="${today()}" value="${today()}" required></label><label class="form-field"><span>Referensi mutasi / transaksi bank *</span><input name="reference" minlength="3" maxlength="160" required placeholder="Nomor referensi atau keterangan mutasi"></label><label class="form-field"><span>Catatan</span><textarea name="note" maxlength="1500" placeholder="Wajib jika meminta perbaikan">${esc(r.note||'')}</textarea></label><label class="check"><input type="checkbox" name="confirm" required>Bukti transfer cocok dengan mutasi bank dan dana sudah diterima.</label><p class="form-error" id="finance-error" role="alert" hidden></p><div class="decision-actions"><button class="btn secondary" type="submit" name="decision" value="return" formnovalidate>Perlu perbaikan</button><button class="btn" type="submit" name="decision" value="approve">Simpan rekonsiliasi</button></div></form>`}`)}
function detail(index){const m=state.payout?.members[index];if(!m)return;show('Rincian bagi hasil',`<h3>${esc(m.memberName)}</h3><p class="subtext">${esc(m.bankName)} · ${esc(m.bankAccount)}<br>${date(state.date)}</p>${table(['AKAD / EFEKTIF NISBAH','MODAL','PERIODE','BAGI HASIL'],m.contracts.map(c=>`<tr><td><strong>${esc(c.contractNumber)}</strong><small>${date(c.effectiveDate)}${c.contractStatus==='generated'?'<br>Menunggu tanda tangan koperasi':''}</small></td><td class="money">${money(c.principal)}</td><td>${c.period}/12</td><td class="money">${money(c.amount)}</td></tr>`).join(''),'')}<div class="finance-total"><span>Total anggota</span><strong>${money(m.amount)}</strong></div>`)}
function csvCell(value,text=false){let s=String(value??'');if(text||/^[\s]*[=+@\-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
function exportCsv(){const p=state.payout;if(!p?.members.length)return;const rows=[['Tanggal','Nomor anggota','Nama anggota','Bank','Nomor rekening','Nama pemilik rekening','Jumlah akad','Total modal (Rp)','Bagi hasil (Rp)'],...p.members.map(m=>[p.date,m.memberId,m.memberName,m.bankName,m.bankAccount,m.accountName,m.contractCount,m.principal,m.amount]),['TOTAL','','','','','',p.contractCount,'',p.total]];const text='\ufeff'+rows.map((r,i)=>r.map((v,j)=>csvCell(v,i>0&&j>=1&&j<=5&&v!=='')).join(';')).join('\r\n');const blob=new Blob([text],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='KSPPS-Bagi-Hasil-'+p.date+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function load(){if(state.loading||role()!=='finance')return;state.loading=true;state.error='';const seq=++state.sequence;announce();try{const [q,p]=await Promise.all([wf().api('/finance/reconciliations'),wf().api('/finance/payouts?date='+encodeURIComponent(state.date))]);if(seq!==state.sequence)return;state.items=q.items;state.payout=p;state.loaded=true;}catch(error){if(seq===state.sequence)state.error=error.message;}finally{if(seq===state.sequence){state.loading=false;announce();}}}
function syncToday(){if(state.followToday&&state.date!==today()&&!state.busy&&!$('#portal-dialog').open){state.date=today();invalidate();return true;}return false;}
function mount(){syncToday();if(role()==='finance'&&location.hash.startsWith('#finance-')&&!state.loaded&&!state.loading&&!state.error)void load();}
function invalidate(){state.loaded=false;state.error='';}
document.addEventListener('click',event=>{const b=event.target.closest('[data-finance-action]');if(!b)return;const a=b.dataset.financeAction;if(a==='close'&&!state.busy)$('#portal-dialog').close();if(a==='refresh'){invalidate();void load();}if(a==='today'&&!state.loading){state.date=today();state.followToday=true;invalidate();void load();}if(a==='reconcile')reconciliationDialog(b.dataset.id,b.dataset.kind);if(a==='detail')detail(Number(b.dataset.index));if(a==='csv')exportCsv();if(a==='payout-complete'&&state.payout?.task){show('Selesaikan persiapan bagi hasil',`<p>Konfirmasi daftar untuk ${date(state.date)} sudah diperiksa.</p><form id="finance-payout-complete"><label class="check"><input name="confirm" type="checkbox" required>Nominal dan rekening tujuan sudah sesuai.</label><p class="field-hint">Ini mencatat pekerjaan persiapan selesai. Status transfer bank tidak berubah.</p><p id="finance-error" class="form-error" role="alert" hidden></p><button type="submit" class="btn">Simpan waktu selesai</button></form>`);}});
document.addEventListener('input',event=>{if(event.target.id==='finance-search'){state.query=event.target.value;$('#finance-queue-table').innerHTML=queueTable();}});
document.addEventListener('change',event=>{if(event.target.id==='finance-filter'){state.filter=event.target.value;$('#finance-queue-table').innerHTML=queueTable();}if(event.target.id==='finance-date'&&event.target.checkValidity()&&event.target.value){state.date=event.target.value;state.followToday=false;invalidate();if(state.loading){state.sequence++;state.loading=false;}void load();}});
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='finance-reconcile-form')return;event.preventDefault();event.stopImmediatePropagation();if(state.busy)return;const decision=event.submitter?.value||'approve';if(decision==='approve'&&!form.checkValidity()){form.reportValidity();return;}if(window.KsppsActivity&&!await window.KsppsActivity.requireStarted(form.dataset.id,'reconciliation'))return;const f=new FormData(form),body={id:form.dataset.id,kind:form.dataset.kind,version:Number(form.dataset.version),sourceVersion:Number(form.dataset.sourceVersion),receivedAmount:f.get('receivedAmount')===''?null:Number(f.get('receivedAmount')),transferDate:f.get('transferDate'),reference:f.get('reference'),note:f.get('note'),confirm:f.get('confirm')==='on',decision};state.busy=true;const error=$('#finance-error');error.hidden=true;form.querySelectorAll('button,input,textarea').forEach(x=>x.disabled=true);try{await wf().api('/finance/reconcile',{method:'POST',body:JSON.stringify(body)});state.busy=false;$('#portal-dialog').close();invalidate();await wf().refresh();void load();}catch(e){state.busy=false;form.querySelectorAll('button,input,textarea').forEach(x=>x.disabled=false);error.textContent=e.message;error.hidden=false;}},true);
document.addEventListener('submit',async event=>{const form=event.target;if(form.id!=='finance-payout-complete')return;event.preventDefault();event.stopImmediatePropagation();if(state.busy||!form.reportValidity())return;state.busy=true;const b=form.querySelector('button');b.disabled=true;try{await wf().api('/finance/payouts/complete',{method:'POST',body:JSON.stringify({date:state.date,taskId:state.payout.task.id,confirm:new FormData(form).get('confirm')==='on'})});state.busy=false;$('#portal-dialog').close();window.KsppsActivity?.invalidate();invalidate();void load();}catch(error){state.busy=false;b.disabled=false;const el=$('#finance-error');el.hidden=false;el.textContent=error.message;}},true);
$('#portal-dialog').addEventListener('cancel',event=>{if(state.busy)event.preventDefault();});
window.addEventListener('kspps-profile-loaded',()=>{if(!$('#portal-dialog').open&&!state.busy)invalidate();});
window.addEventListener('kspps-staff-role-changed',()=>{state.sequence++;state.loading=false;invalidate();});
window.addEventListener('kspps-member-changed',()=>{state.sequence++;state.loading=false;state.items=[];state.payout=null;invalidate();});
setInterval(()=>{if(syncToday()&&role()==='finance'&&location.hash.startsWith('#finance-'))void load();},60000);
window.KsppsFinance={page:key=>key==='finance-rekonsiliasi'?queuePage():key==='finance-bagi-hasil'?payoutPage():dashboard(),mount};
})();
